// Compact, offline copies of the original photographs. Each inline image is under 52 KiB decoded.
(() => {
  "use strict";
  const pending = new Map();
  function load(src) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error("图片未能载入"));
      image.src = src;
    });
  }
  function ready(key) {
    if (!pending.has(key)) {
      const entry = sources[key];
      const result = load(entry[0]).catch(() => load(entry[1])).catch(error => {
        pending.delete(key);
        throw error;
      });
      pending.set(key, result);
    }
    return pending.get(key);
  }
  function copy(key) {
    const node = new Image();
    node.alt = "";
    ready(key).then(image => {node.src = image.src;}).catch(() => {node.alt = sources[key][2];});
    return node;
  }
  const sources = {
  "strawberry": [
    "data:image/webp;base64,",
    "./assets/strawberry.png",
    "草莓片"
  ],
  "blueberry": [
    "data:image/webp;base64,",
    "./assets/blueberry.png",
    "蓝莓"
  ],
  "wafer": [
    "data:image/webp;base64,",
    "./assets/wafer.png",
    "威化饼"
  ],
  "chocobanana": [
    "data:image/png;base64,",
    "./assets/chocobanana.png",
    "巧克香蕉"
  ],
  "cream": [
    "./assets/cream.jpg",
    "data:image/webp;base64,",
    "奶油纹理"
  ]
};
  window.CupPhotos = {ready,copy};
})();
